    map3(q + e.xyy, tension, thick) - map3(q - e.xyy, tension, thick),
    map3(q + e.yxy, tension, thick) - map3(q - e.yxy, tension, thick),
    map3(q + e.yyx, tension, thick) - map3(q - e.yyx, tension, thick)
